import net.minecraft.item.ItemStack;
import net.minecraft.network.play.client.C07PacketPlayerDigging;
import net.minecraft.util.BlockPos;
import net.minecraft.util.EnumFacing;

import java.util.ArrayList;
import java.util.function.Consumer;

public class Breaker extends Module {
    public Breaker() {
        super("BlockFucker", 0, Module.Category.MISC);
        ArrayList<Block> defaultList = new ArrayList<>();
        defaultList.add(Blocks.cake);
        defaultList.add(Blocks.bed);
        defaultList.add(Blocks.wool);
        defaultList.add(Blocks.end_stone);
        this.addBlockSelection("Target Blocks", defaultList);
        this.addBoolean("Cake Check", true);
    }

    @Handler
    public Consumer<UpdateEvent> onEvent = (event) -> {
        final int radius = 5;
        BlockSelectionSetting setting = (BlockSelectionSetting) Memeware.INSTANCE.getSettingsManager().getSettingByMod(this.getClass(), "Target Blocks");
        for (int x = -radius; x < radius; ++x) {
            for (int y2 = radius; y2 > -radius; --y2) {
                for (int z = -radius; z < radius; ++z) {
                    final int xPos = (int) this.mc.thePlayer.posX + x;
                    final int yPos = (int) this.mc.thePlayer.posY + y2;
                    final int zPos = (int) this.mc.thePlayer.posZ + z;
                    final BlockPos blockPos = new BlockPos(xPos, yPos, zPos);
                    final Block block = this.mc.theWorld.getBlockState(blockPos).getBlock();
                    if (block == Blocks.cake || block == Blocks.end_stone) {
                        PacketUtil.sendPacketSilent(new C07PacketPlayerDigging(C07PacketPlayerDigging.Action.START_DESTROY_BLOCK, blockPos, EnumFacing.NORTH));
                        PacketUtil.sendPacketSilent(new C07PacketPlayerDigging(C07PacketPlayerDigging.Action.STOP_DESTROY_BLOCK, blockPos, EnumFacing.NORTH));
                    }
                }
            }
        }
    };

    private void breakBlock(BlockPos blockPos) {
        PacketUtil.sendPacketSilent(new C07PacketPlayerDigging(C07PacketPlayerDigging.Action.START_DESTROY_BLOCK, blockPos, EnumFacing.NORTH));
        PacketUtil.sendPacketSilent(new C07PacketPlayerDigging(C07PacketPlayerDigging.Action.STOP_DESTROY_BLOCK, blockPos, EnumFacing.NORTH));
    }

    private int pickaxeSlot() {
        for (int j = 0; j < 8; ++j) {
            ItemStack stack = mc.thePlayer.inventory.mainInventory[j];
            if (stack != null && stack.getItem() instanceof ItemPickaxe) {
                return j;
            }
        }
        return -10;
    }

    private boolean cakeBesideOrAt(BlockPos blockPos) {
        for (EnumFacing face : new EnumFacing[] {EnumFacing.NORTH, EnumFacing.SOUTH, EnumFacing.WEST, EnumFacing.EAST, EnumFacing.DOWN}) {
            if (mc.theWorld.getBlockState(blockPos.offset(face)).getBlock() == Blocks.cake) {
                return true;
            }
        }
        return mc.theWorld.getBlockState(blockPos).getBlock() == Blocks.cake;
    }

    private boolean cakeCovered(BlockPos blockPos) {
        for (EnumFacing face : new EnumFacing[] {EnumFacing.NORTH, EnumFacing.SOUTH, EnumFacing.WEST, EnumFacing.EAST, EnumFacing.UP}) {
            if (mc.theWorld.getBlockState(blockPos.offset(face)).getBlock() == Blocks.air) {
                return false;
            }
        }
        return true;
    }
}


// NOTE (AI): Registered as BlockFucker. The UpdateEvent handler scans a 5-block cube around the player and, when the block is cake or end stone, sends START then STOP with EnumFacing.NORTH via sendPacketSilent (the bus-bypassing path). The pickaxeSlot, cakeBesideOrAt and cakeCovered helpers are dead code; the actual target list comes from the BlockSelectionSetting populated with cake, bed, wool and end stone defaults. This is the bedwars-style block destroyer: it only ever touches C07 and never sends C08 placements or C0A swings, so the only server-side evidence is the instant-break packet pair.

// ===== FILE: Tenacity 6.0 — dev/tenacity/event/impl/player/SpeedMine.java =====
package dev.tenacity.event.impl.player;

import dev.tenacity.module.ModuleCategory;
import dev.tenacity.module.Module;
import dev.tenacity.event.IEventListener;
import dev.tenacity.event.impl.network.PacketSendEvent;
import dev.tenacity.event.impl.player.MotionEvent;
import dev.tenacity.setting.impl.NumberSetting;
import dev.tenacity.util.network.PacketUtils;
import net.minecraft.block.state.IBlockState;
import net.minecraft.init.Blocks;
import net.minecraft.network.play.client.C07PacketPlayerDigging;
import net.minecraft.util.BlockPos;
import net.minecraft.util.EnumFacing;

public class SpeedMine extends Module {

    private final NumberSetting speed = new NumberSetting("Speed", 1.5, 1, 3, 0.1);
    private EnumFacing facing;
    private BlockPos pos;
    private boolean boost;
    private float damage;

    public SpeedMine() {
        super("SpeedMine", "mines blocks faster", ModuleCategory.PLAYER);
       initializeSettings(speed);
    }

    private final IEventListener<MotionEvent> onMotion = e -> {
        if (e.isPre()) {
            mc.playerController.blockHitDelay = 0;
            if (pos != null && boost) {
                IBlockState blockState = mc.theWorld.getBlockState(pos);
                if (blockState == null) return;

                try {
                    damage += (float) (blockState.getBlock().getPlayerRelativeBlockHardness(mc.thePlayer, mc.theWorld, pos) * speed.getCurrentValue());
                } catch (Exception ex) {
                    ex.printStackTrace();
                    return;
                }

                if (damage >= 1) {
                    try {
                        mc.theWorld.setBlockState(pos, Blocks.air.getDefaultState(), 11);
                    } catch (Exception ex) {
                        ex.printStackTrace();
                        return;
                    }
                    PacketUtils.sendPacketNoEvent(new C07PacketPlayerDigging(C07PacketPlayerDigging.Action.STOP_DESTROY_BLOCK, pos, facing));
                    damage = 0;
                    boost = false;
                }
            }
        }
    };

    private final IEventListener<PacketSendEvent> onPacketSend = e -> {
        if (e.getPacket() instanceof C07PacketPlayerDigging) {
            C07PacketPlayerDigging packet = (C07PacketPlayerDigging) e.getPacket();
            if (packet.getStatus() == C07PacketPlayerDigging.Action.START_DESTROY_BLOCK) {
                boost = true;
                pos = packet.getPosition();
                facing = packet.getFacing();
                damage = 0;
            } else if (packet.getStatus() == C07PacketPlayerDigging.Action.ABORT_DESTROY_BLOCK | packet.getStatus() == C07PacketPlayerDigging.Action.STOP_DESTROY_BLOCK) {
                boost = false;
                pos = null;
                facing = null;
            }
        }
    };

}


// NOTE (AI): SpeedMine sits in the event package but is a real Module. It does not fake the dig time; it runs the block-breaking math client-side. On PacketSendEvent it arms on START_DESTROY_BLOCK, records pos and facing, and disarms on ABORT or STOP. While armed, every pre-motion tick accumulates damage += playerRelativeBlockHardness * speed, and when damage reaches 1 it swaps the block to air client-side (setBlockState) and sends STOP_DESTROY_BLOCK without event. The server receives a legitimately-timed STOP and processes the break normally; the client-side air swap is what makes the block vanish instantly for the local player, and the server's own damage counter never has to reach the threshold. blockHitDelay=0 removes the vanilla post-hit delay that would otherwise slow the next block.

